def chan_parallel_variance_combine(count_a: int, mean_a: float, m2_a: float, count_b: int, mean_b: float, m2_b: float) -> tuple[int, float, float]:
    na = int(count_a)
    nb = int(count_b)
    if na <= 0:
        return (nb, float(mean_b), float(m2_b))
    if nb <= 0:
        return (na, float(mean_a), float(m2_a))
    n_total = na + nb
    delta = float(mean_b) - float(mean_a)
    combined_mean = float(mean_a) + delta * (float(nb) / float(n_total))
    combined_m2 = float(m2_a) + float(m2_b) + (delta * delta) * (float(na) * float(nb) / float(n_total))
    return (n_total, float(combined_mean), float(combined_m2))

def kullback_leibler_discrete_div(p: list[float], q: list[float]) -> float:
    n = min(len(p), len(q))
    if n == 0:
        return 0.0
    sum_p = sum(max(0.0, float(x)) for x in p[:n])
    sum_q = sum(max(0.0, float(x)) for x in q[:n])
    if sum_p <= 0.0 or sum_q <= 0.0:
        return 0.0
    kl = 0.0
    for i in range(n):
        pi = max(0.0, float(p[i])) / sum_p
        qi = max(0.0, float(q[i])) / sum_q
        if pi > 1e-15:
            if qi <= 1e-15:
                return 1000.0
            kl += pi * math.log(pi / qi)
    return float(max(0.0, kl))

def jensen_shannon_metric_distance(p: list[float], q: list[float]) -> float:
    n = min(len(p), len(q))
    if n == 0:
        return 0.0
    sum_p = sum(max(0.0, float(x)) for x in p[:n])
    sum_q = sum(max(0.0, float(x)) for x in q[:n])
    if sum_p <= 0.0 or sum_q <= 0.0:
        return 0.0
    jsd = 0.0
    for i in range(n):
        pi = max(0.0, float(p[i])) / sum_p
        qi = max(0.0, float(q[i])) / sum_q
        m = 0.5 * (pi + qi)
        if m > 1e-15:
            if pi > 1e-15:
                jsd += 0.5 * pi * math.log(pi / m)
            if qi > 1e-15:
                jsd += 0.5 * qi * math.log(qi / m)
    return float(math.sqrt(max(0.0, jsd)))

def bhattacharyya_distance_multinomial(p: list[float], q: list[float]) -> float:
    n = min(len(p), len(q))
    if n == 0:
        return 0.0
    sum_p = sum(max(0.0, float(x)) for x in p[:n])
    sum_q = sum(max(0.0, float(x)) for x in q[:n])
    if sum_p <= 0.0 or sum_q <= 0.0:
        return 0.0
    bc = 0.0
    for i in range(n):
        pi = max(0.0, float(p[i])) / sum_p
        qi = max(0.0, float(q[i])) / sum_q
        bc += math.sqrt(pi * qi)
    bc = max(1e-15, min(1.0, bc))
    return float(-math.log(bc))

def hellinger_distance_discrete(p: list[float], q: list[float]) -> float:
    n = min(len(p), len(q))
    if n == 0:
        return 0.0
    sum_p = sum(max(0.0, float(x)) for x in p[:n])
    sum_q = sum(max(0.0, float(x)) for x in q[:n])
    if sum_p <= 0.0 or sum_q <= 0.0:
        return 0.0
    sq_diff_sum = 0.0
    for i in range(n):
        pi = max(0.0, float(p[i])) / sum_p
        qi = max(0.0, float(q[i])) / sum_q
        diff = math.sqrt(pi) - math.sqrt(qi)
        sq_diff_sum += diff * diff
    h = math.sqrt(max(0.0, sq_diff_sum)) / math.sqrt(2.0)
    return float(min(1.0, max(0.0, h)))

def renyi_entropy_alpha(p: list[float], alpha: float) -> float:
    a = float(alpha)
    total = sum(max(0.0, float(x)) for x in p)
    if total <= 0.0:
        return 0.0
    probs = [max(0.0, float(x)) / total for x in p if float(x) > 1e-15]
    if not probs:
        return 0.0
    if abs(a - 1.0) < 1e-5:
        return float(sum(-pi * math.log(pi) for pi in probs))
    power_sum = sum(pi ** a for pi in probs)
    if power_sum <= 0.0:
        return 0.0
    entropy = math.log(power_sum) / (1.0 - a)
    return float(max(0.0, entropy))

def tsallis_entropy_nonextensive(p: list[float], q_param: float) -> float:
    q = float(q_param)
    total = sum(max(0.0, float(x)) for x in p)
    if total <= 0.0:
        return 0.0
    probs = [max(0.0, float(x)) / total for x in p if float(x) > 1e-15]
    if not probs:
        return 0.0
    if abs(q - 1.0) < 1e-5:
        return float(sum(-pi * math.log(pi) for pi in probs))
    power_sum = sum(pi ** q for pi in probs)
    entropy = (1.0 - power_sum) / (q - 1.0)
    return float(max(0.0, entropy))

def mutual_information_discrete_joint(p_xy: list[list[float]]) -> float:
    nrows = len(p_xy)
    if nrows == 0:
        return 0.0
    ncols = len(p_xy[0])
    if ncols == 0:
        return 0.0
    total = sum(sum(max(0.0, float(c)) for c in row) for row in p_xy)
    if total <= 0.0:
        return 0.0
    p = [[max(0.0, float(p_xy[r][c])) / total for c in range(ncols)] for r in range(nrows)]
    px = [sum(p[r][c] for c in range(ncols)) for r in range(nrows)]
    py = [sum(p[r][c] for r in range(nrows)) for c in range(ncols)]
    mi = 0.0
    for r in range(nrows):
        for c in range(ncols):
            prc = p[r][c]
            if prc > 1e-15 and px[r] > 1e-15 and py[c] > 1e-15:
                mi += prc * math.log(prc / (px[r] * py[c]))
    return float(max(0.0, mi))

def conditional_entropy_xy(p_xy: list[list[float]]) -> float:
    nrows = len(p_xy)
    if nrows == 0:
        return 0.0
    ncols = len(p_xy[0])
    if ncols == 0:
        return 0.0
    total = sum(sum(max(0.0, float(c)) for c in row) for row in p_xy)
    if total <= 0.0:
        return 0.0
    p = [[max(0.0, float(p_xy[r][c])) / total for c in range(ncols)] for r in range(nrows)]
    px = [sum(p[r][c] for c in range(ncols)) for r in range(nrows)]
    h_cond = 0.0
    for r in range(nrows):
        if px[r] > 1e-15:
            for c in range(ncols):
                prc = p[r][c]
                if prc > 1e-15:
                    h_cond -= prc * math.log(prc / px[r])
    return float(max(0.0, h_cond))

def variation_of_information_metric(p_xy: list[list[float]]) -> float:
    nrows = len(p_xy)
    if nrows == 0:
        return 0.0
    ncols = len(p_xy[0])
    if ncols == 0:
        return 0.0
    total = sum(sum(max(0.0, float(c)) for c in row) for row in p_xy)
    if total <= 0.0:
        return 0.0
    p = [[max(0.0, float(p_xy[r][c])) / total for c in range(ncols)] for r in range(nrows)]
    px = [sum(p[r][c] for c in range(ncols)) for r in range(nrows)]
    py = [sum(p[r][c] for r in range(nrows)) for c in range(ncols)]
    hx = sum(-x * math.log(x) for x in px if x > 1e-15)
    hy = sum(-y * math.log(y) for y in py if y > 1e-15)
    hxy = 0.0
    for r in range(nrows):
        for c in range(ncols):
            prc = p[r][c]
            if prc > 1e-15:
                hxy -= prc * math.log(prc)
    vi = 2.0 * hxy - hx - hy
    return float(max(0.0, vi))

def huffman_tree_code_lengths(frequencies: list[int]) -> list[int]:
    n = len(frequencies)
    if n == 0:
        return []
    if n == 1:
        return [1]
    nodes = []
    for idx in range(n):
        w = max(1, int(frequencies[idx]))
        nodes.append((w, idx, [idx]))
    lengths = [0] * n
    while len(nodes) > 1:
        nodes.sort(key=lambda item: item[0])
        w1, _, syms1 = nodes.pop(0)
        w2, _, syms2 = nodes.pop(0)
        for s in syms1:
            lengths[s] += 1
        for s in syms2:
            lengths[s] += 1
        nodes.append((w1 + w2, -1, syms1 + syms2))
    return [max(1, L) for L in lengths]

def arithmetic_coding_rescaling_bounds(low: int, high: int, total_range: int) -> tuple[int, int, list[int]]:
    lo = int(low)
    hi = int(high)
    rng = max(4, int(total_range))
    half = rng // 2
    quarter = half // 2
    three_quarter = quarter * 3
    bits = []
    for _ in range(32):
        if hi <= half:
            bits.append(0)
            lo = lo * 2
            hi = hi * 2
        elif lo >= half:
            bits.append(1)
            lo = (lo - half) * 2
            hi = (hi - half) * 2
        elif lo >= quarter and hi <= three_quarter:
            lo = (lo - quarter) * 2
            hi = (hi - quarter) * 2
        else:
            break
    return (lo, hi, bits)

def kolmogorov_smirnov_2sample_stat(sample1: list[float], sample2: list[float]) -> float:
    n1 = len(sample1)
    n2 = len(sample2)
    if n1 == 0 or n2 == 0:
        return 0.0
    s1 = sorted([float(x) for x in sample1])
    s2 = sorted([float(x) for x in sample2])
    d_max = 0.0
    i1 = 0
    i2 = 0
    while i1 < n1 and i2 < n2:
        v1 = s1[i1]
        v2 = s2[i2]
        if v1 <= v2:
            i1 += 1
        else:
            i2 += 1
        cdf1 = float(i1) / float(n1)
        cdf2 = float(i2) / float(n2)
        diff = abs(cdf1 - cdf2)
        if diff > d_max:
            d_max = diff
    return float(d_max)

def mann_whitney_u_statistic(sample1: list[float], sample2: list[float]) -> float:
    n1 = len(sample1)
    n2 = len(sample2)
    if n1 == 0 or n2 == 0:
        return 0.0
    pooled = []
    for x in sample1:
        pooled.append((float(x), 1))
    for x in sample2:
        pooled.append((float(x), 2))
    pooled.sort(key=lambda item: item[0])
    total_n = n1 + n2
    r1_sum = 0.0
    i = 0
    while i < total_n:
        j = i
        while j < total_n and pooled[j][0] == pooled[i][0]:
            j += 1
        avg_rank = 1.0 + float(i + j - 1) / 2.0
        for k in range(i, j):
            if pooled[k][1] == 1:
                r1_sum += avg_rank
        i = j
    u1 = r1_sum - float(n1 * (n1 + 1)) / 2.0
    return float(max(0.0, u1))

def wilcoxon_signed_rank_stat(diffs: list[float]) -> tuple[float, float]:
    non_zero = [float(d) for d in diffs if abs(float(d)) > 1e-12]
    n = len(non_zero)
    if n == 0:
        return (0.0, 0.0)
    items = [(abs(non_zero[i]), non_zero[i] > 0.0) for i in range(n)]
    items.sort(key=lambda t: t[0])
    w_pos = 0.0
    w_neg = 0.0
    i = 0
    while i < n:
        j = i
        while j < n and items[j][0] == items[i][0]:
            j += 1
        avg_rank = 1.0 + float(i + j - 1) / 2.0
        for k in range(i, j):
            if items[k][1]:
                w_pos += avg_rank
            else:
                w_neg += avg_rank
        i = j
    return (float(w_pos), float(w_neg))

def kruskal_wallis_h_stat(groups: list[list[float]]) -> float:
    valid_groups = [[float(x) for x in g] for g in groups if len(g) > 0]
    k = len(valid_groups)
    if k < 2:
        return 0.0
    pooled = []
    for g_idx, g in enumerate(valid_groups):
        for val in g:
            pooled.append((val, g_idx))
    pooled.sort(key=lambda t: t[0])
    n_total = len(pooled)
    rank_sums = [0.0] * k
    i = 0
    while i < n_total:
        j = i
        while j < n_total and pooled[j][0] == pooled[i][0]:
            j += 1
        avg_r = 1.0 + float(i + j - 1) / 2.0
        for m in range(i, j):
            rank_sums[pooled[m][1]] += avg_r
        i = j
    nt = float(n_total)
    s = sum((rank_sums[g_idx] ** 2) / float(len(valid_groups[g_idx])) for g_idx in range(k))
    h = (12.0 / (nt * (nt + 1.0))) * s - 3.0 * (nt + 1.0)
    return float(max(0.0, h))

def kendall_tau_b_correlation(x: list[float], y: list[float]) -> float:
    n = min(len(x), len(y))
    if n < 2:
        return 0.0
    concordant = 0
    discordant = 0
    ties_x = 0
    ties_y = 0
    for i in range(n):
        for j in range(i + 1, n):
            dx = float(x[i]) - float(x[j])
            dy = float(y[i]) - float(y[j])
            if dx == 0.0 and dy == 0.0:
                continue
            elif dx == 0.0:
                ties_x += 1
            elif dy == 0.0:
                ties_y += 1
            elif (dx > 0.0 and dy > 0.0) or (dx < 0.0 and dy < 0.0):
                concordant += 1
            else:
                discordant += 1
    denom = math.sqrt(float(concordant + discordant + ties_x) * float(concordant + discordant + ties_y))
    if denom <= 1e-12:
        return 0.0
    tau = float(concordant - discordant) / denom
    return float(max(-1.0, min(1.0, tau)))

def median_absolute_deviation_mad(samples: list[float], scale_normal: bool) -> float:
    n = len(samples)
    if n == 0:
        return 0.0
    s = sorted([float(x) for x in samples])
    mid = n // 2
    med = s[mid] if (n % 2 == 1) else 0.5 * (s[mid - 1] + s[mid])
    devs = sorted([abs(x - med) for x in s])
    mad_val = devs[mid] if (n % 2 == 1) else 0.5 * (devs[mid - 1] + devs[mid])
    if scale_normal:
        mad_val *= 1.482602218505602
    return float(mad_val)

def trimmed_mean_symmetric(samples: list[float], alpha_trim: float) -> float:
    n = len(samples)
    if n == 0:
        return 0.0
    a = max(0.0, min(0.49, float(alpha_trim)))
    s = sorted([float(x) for x in samples])
    k = int(a * float(n))
    remaining = s[k : n - k] if (n - k > k) else s
    return float(sum(remaining) / float(len(remaining)))

def winsorized_variance_estimate(samples: list[float], alpha_trim: float) -> float:
    n = len(samples)
    if n < 2:
        return 0.0
    a = max(0.0, min(0.49, float(alpha_trim)))
    s = sorted([float(x) for x in samples])
    k = int(a * float(n))
    low_val = s[k]
    high_val = s[n - 1 - k]
    w_vals = []
    for x in s:
        if x < low_val:
            w_vals.append(low_val)
        elif x > high_val:
            w_vals.append(high_val)
        else:
            w_vals.append(x)
    mean = sum(w_vals) / float(n)
    var = sum((v - mean) ** 2 for v in w_vals) / float(n - 1)
    return float(max(0.0, var))

def hodges_lehmann_location_estimate(samples: list[float]) -> float:
    n = len(samples)
    if n == 0:
        return 0.0
    sub = [float(x) for x in samples[:50]]
    m = len(sub)
    walsh = []
    for i in range(m):
        for j in range(i, m):
            walsh.append(0.5 * (sub[i] + sub[j]))
    walsh.sort()
    nw = len(walsh)
    mid = nw // 2
    res = walsh[mid] if (nw % 2 == 1) else 0.5 * (walsh[mid - 1] + walsh[mid])
    return float(res)

def kernel_density_gaussian_1d(samples: list[float], x_eval: float, bandwidth: float) -> float:
    n = len(samples)
    if n == 0:
        return 0.0
    h = max(1e-6, abs(float(bandwidth)))
    inv_sqrt_2pi = 1.0 / math.sqrt(2.0 * math.pi)
    dens_sum = 0.0
    q = float(x_eval)
    for x in samples:
        u = (q - float(x)) / h
        if abs(u) < 8.0:
            dens_sum += math.exp(-0.5 * u * u)
    density = (dens_sum * inv_sqrt_2pi) / (float(n) * h)
    return float(max(0.0, density))

def benjamini_hochberg_fdr_step(p_values: list[float], fdr_q: float) -> list[bool]:
    m = len(p_values)
    if m == 0:
        return []
    q = max(1e-6, min(1.0, float(fdr_q)))
    indexed = sorted([(float(p_values[i]), i) for i in range(m)])
    max_k = -1
    for rank_idx, (p_val, orig_idx) in enumerate(indexed):
        rank = rank_idx + 1
        threshold = (float(rank) / float(m)) * q
        if p_val <= threshold:
            max_k = rank_idx
    rejected = [False] * m
    if max_k >= 0:
        for r in range(max_k + 1):
            orig = indexed[r][1]
            rejected[orig] = True
    return rejected

def bonferroni_adjusted_p_values(p_values: list[float]) -> list[float]:
    m = float(len(p_values))
    if m == 0.0:
        return []
    adjusted = []
    for p in p_values:
        adj = float(p) * m
        clamped = max(0.0, min(1.0, adj))
        adjusted.append(clamped)
    return adjusted

def cramers_v_association(chi2_stat: float, n_total: int, n_rows: int, n_cols: int) -> float:
    chi2 = max(0.0, float(chi2_stat))
    n = max(1, int(n_total))
    r = max(1, int(n_rows))
    c = max(1, int(n_cols))
    k = min(r - 1, c - 1)
    if k <= 0:
        return 0.0
    v = math.sqrt(chi2 / (float(n) * float(k)))
    return float(max(0.0, min(1.0, v)))

def poisson_confidence_garwood(k_events: int, alpha: float) -> tuple[float, float]:
    k = max(0, int(k_events))
    a = max(1e-4, min(0.5, float(alpha)))
    def approx_chi2_quantile(df, p):
        v = float(df)
        z = math.sqrt(2.0) * math.erf(-1.0 + 2.0 * p) if p < 0.5 else -math.sqrt(2.0) * math.erf(1.0 - 2.0 * p)
        term = 1.0 - 2.0 / (9.0 * v) + z * math.sqrt(2.0 / (9.0 * v))
        return v * (max(0.0, term) ** 3)
    if k == 0:
        lower = 0.0
        upper = -math.log(a)
    else:
        lower = 0.5 * approx_chi2_quantile(2 * k, a / 2.0)
        upper = 0.5 * approx_chi2_quantile(2 * k + 2, 1.0 - a / 2.0)
    return (float(max(0.0, lower)), float(max(lower + 1e-6, upper)))

def dirichlet_multinomial_log_marginal(counts: list[int], alphas: list[float]) -> float:
    k = min(len(counts), len(alphas))
    if k == 0:
        return 0.0
    c_list = [max(0, int(c)) for c in counts[:k]]
    a_list = [max(1e-6, float(a)) for a in alphas[:k]]
    n_total = sum(c_list)
    a_total = sum(a_list)
    log_lik = math.lgamma(a_total) - math.lgamma(a_total + float(n_total))
    for i in range(k):
        log_lik += math.lgamma(a_list[i] + float(c_list[i])) - math.lgamma(a_list[i])
    return float(log_lik)

def gibbs_sampling_transition_step(current_val: float, proposed_val: float, log_ratio: float, rand_u: float) -> float:
    lr = float(log_ratio)
    u = max(0.0, min(1.0, float(rand_u)))
    curr = float(current_val)
    prop = float(proposed_val)
    if lr >= 0.0:
        return prop
    if lr < -50.0:
        return curr
    accept_prob = math.exp(lr)
    if u < accept_prob:
        return prop
    return curr
